full_js.searchPrvcntr:
function searchPrvcntr() {
	$("#inpSrchCate").val($("#searchCate").val());
	$("#inpSrchTxt").val($("#searchTxt").val());
	$("#statDiv").val($("#searchStatDiv").val());
	
	var beginDtVal = $("#bDt").val();
	var endDtVal = $("#eDt").val();
	var beginDt = new Date($("#bDt").datepicker("getDate"));
	var endDt = new Date($("#eDt").datepicker("getDate"));
	
	if( beginDtVal == "" || endDtVal == ""){
		alert('검색할 데이터 기간을 입력하세요.(최대 1개월)');
		return;
	}
	
	// 기간 체크
	if ( beginDt != "" && endDt != "") {
		if( endDt - beginDt < 0){
			alert('기간이 옳바르지 않습니다.');
			return;
		}
	}
	
	var cal = (endDt - beginDt)/(24 * 3600 * 1000);
	
	if(cal > 31){
		alert("최대 1개월간 자료를 검색 할 수 있습니다.");
		return;
	}
	
	searchPrvcntrList();
}

full_js.searchPrvcntrList:
function searchPrvcntrList() {
	$('#currPage').val(1);
	
	var instClCd = $("#searchinstClCd option:selected").val();
	$("#instClCd").val(instClCd);
	var inpSrchwrd = $("#searchinpSrchwrd").val();
	$("#inpSrchwrd").val(inpSrchwrd);
	var searchinpSrchwrdNm = $("#searchinpSrchwrdNm").val();
	$("#inpSrchwrdNm").val(searchinpSrchwrdNm);
	var inpAmt = $("#searchinpAmt").val();
	$("#inpAmt").val(inpAmt);
	var scl = $("#searchscl option:selected").val();
	$("#scl").val(scl);
	var fond = $("#searchfond option:selected").val();
	$("#fond").val(fond);
	var instClCdTy1 = $('input:checkbox[id="searchinstClCdTy1"]').is(":checked");
	if(instClCdTy1) {
		$("#instClCdTy1").val("4");
	} else {
		$("#instClCdTy1").val("");	
	}
	var instClCdTy2 = $('input:checkbox[id="searchinstClCdTy2"]').is(":checked");
	if(instClCdTy2) {
		$("#instClCdTy2").val("5");
	} else {
		$("#instClCdTy2").val("");	
	}
	var accnutYear = $("#searchaccnutY option:selected").val(); 
	$("#accnutYear").val(accnutYear);
	
	var inpBdt = $("#bDt").val();
	$("#inpBdt").val(inpBdt);
	var inpEdt = $("#eDt").val();
	$("#inpEdt").val(inpEdt);
	
	if($("#inpAmt").val() < 1000000){
		alert("100만원이상의 금액을 검색하세요.");
		return false;
	} else {
		
		dataLoadingStart();
	}
	
	$('#irListProm').attr('action', '/main/ir/selectPrvcntrInfoList.do?mi=31735').submit();
}

full_js.goParamPage:
function goParamPage( setVal, setNm, setUrl ) {
	$("#paramNm").val(setNm);
	$("#paramVal").val(setVal);
	setTrimMenuId();
	$("#mainMenuForm").attr('action', setUrl).submit();
}

